روزهای نگهداشت موجودی این ماه 27 روز بلندتر شده و پول بیشتری در انبار خوابیده. دقیقاً کجا و چرا؟ (مدیر انبار و زنجیرهٔ تأمین — پخش نوشیدنی و آب‌میوه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "inventory_levels",
      "description": "موجودی میانگین و مصرف به تفکیک دسته و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "avg_inventory_m_toman",
        "usage_m_toman"
      ]
    },
    {
      "dataset": "reorder_history",
      "description": "تاریخچهٔ نقطهٔ سفارش و سفارش‌های مجدد",
      "dimensions": [
        "category",
        "date"
      ],
      "measures": [
        "reorder_point",
        "order_qty"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_on_hand",
      "description": "روزهای نگهداشت",
      "formula": "میانگین موجودی / مصرف روزانه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "holding_cost",
      "description": "هزینهٔ نگهداشت موجودی",
      "formula": "ارزش موجودی × نرخ نگهداشت سالانه",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی",
    "معیار اصلی ارزیابی: نرخ پوشش سفارش بدون رشد نامتناسب موجودی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "days_on_hand"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "days_on_hand": {
    "prev_month": 39,
    "curr_month": 66,
    "change": 27
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "inventory_levels",
    "filters": {
      "period": "curr_month"
    }
  }
}

