به‌عنوان مدیرعامل می‌خواهم بدانم مهم‌ترین ریسک زنجیرهٔ تأمین ما چیست و اولویت سرمایه‌گذاری کجا باشد. (مدیر انبار و زنجیرهٔ تأمین در گفتگو با مدیرعامل — زنجیرهٔ دارو و ملزومات)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "supplier_orders",
      "description": "سفارش‌های خرید: تاریخ ثبت، تاریخ تحویل و تأمین‌کننده",
      "dimensions": [
        "supplier",
        "order"
      ],
      "measures": [
        "lead_time_days"
      ]
    },
    {
      "dataset": "dead_stock_report",
      "description": "گزارش کالای راکد (بدون حرکت در ۹۰ روز)",
      "dimensions": [
        "category"
      ],
      "measures": [
        "value_m_toman",
        "age_days"
      ]
    },
    {
      "dataset": "backorder_log",
      "description": "سفارش‌های عقب‌افتاده به تفکیک روز",
      "dimensions": [
        "date",
        "category"
      ],
      "measures": [
        "orders"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "fill_rate",
      "description": "نرخ پوشش سفارش",
      "formula": "سفارش‌های تکمیل‌شده / کل سفارش‌ها",
      "unit": "درصد",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "supplier_lead_time",
      "description": "زمان تحویل تأمین‌کننده",
      "formula": "میانگین روز از ثبت سفارش تا تحویل",
      "unit": "روز",
      "dimensions": [
        "supplier",
        "period"
      ]
    },
    {
      "metric": "dead_stock",
      "description": "ارزش کالای راکد (بدون حرکت ۹۰ روز)",
      "formula": "جمع ارزش اقلام راکد",
      "unit": "میلیون تومان",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی",
    "معیار اصلی ارزیابی: نرخ پوشش سفارش بدون رشد نامتناسب موجودی"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_orders",
    "filters": {
      "period": "last_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "supplier_concentration_pct": 64,
  "lead_time_external_days": 59,
  "note": "تأمین‌کنندهٔ خارجی تنها منبع ۷۰٪ ارزش موجودی است"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "dead_stock_report",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "dead_stock_share_pct": 12,
  "value_m_toman": 500
